68: function readBody(req) {
69:   return new Promise((resolve, reject) => {
70:     const chunks = [];
71:     let total = 0;
72:     req.on('data', (chunk) => {
73:       total += chunk.length;
74:       if (total > 1000000) {
75:         reject(new Error('body_too_large'));
76:         return;
77:       }
78:       chunks.push(chunk);
79:     });
80:     req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
81:     req.on('error', reject);
82:   });
83: }
